WITH q AS (INSERT INTO project_requirements (project_id, id, kind, area, text, satisfied, title) VALUES ($1, 'FR-PROBE-9990', 'FR', 'проба', 'проба самотеста', true, 'проба самотеста') RETURNING id), n AS (INSERT INTO project_needs (project_id, id, number, text, priority) VALUES ($1, 'N-PROBE-9990', 9990, 'проба самотеста', 'must') RETURNING id), l AS (INSERT INTO project_requirement_needs (project_id, requirement_id, need_id) SELECT $1, q.id, n.id FROM q, n RETURNING requirement_id) INSERT INTO entity_stamp (project_id, kind, id, text_hash, created_at, updated_at) SELECT $1, 'requirement', q.id, 'probe-selftest', ((extract(epoch from now()) * 1000)::bigint - 172800000), ((extract(epoch from now()) * 1000)::bigint - 172800000) FROM q UNION ALL SELECT $1, 'need', n.id, 'probe-selftest', ((extract(epoch from now()) * 1000)::bigint - 172800000), (extract(epoch from now()) * 1000)::bigint FROM n
